// Synthetic states use owned DAT/iscript files; no game data is compiled in.
// Real native training, orders, missile launch and damage exercise AI opcodes.
#include "campaign_ai.h"
#include <cassert>
#include <fstream>
#include <cstdio>
#include <set>
using namespace bwgame;using port3ds::detail::CampaignAI;
static void put(a_vector<uint8_t>& b,unsigned at,unsigned v,unsigned n){for(unsigned i=0;i<n;++i)b.at(at+i)=v>>(i*8);}
static void code(CampaignAI& ai,const a_vector<uint8_t>& instructions){a_vector<uint8_t> bank(36);put(bank,0,4,4);put(bank,4,0x54534554,4);put(bank,8,36,4);bank.insert(bank.end(),instructions.begin(),instructions.end());ai.load([&](a_vector<uint8_t>& out,const a_string& name){if(name=="scripts/aiscript.bin")out=bank;else{out.assign(12,0);put(out,0,4,4);}});}
static void init(game_player& p,const char* path){std::ifstream in(path,std::ios::binary);a_vector<uint8_t> map((std::istreambuf_iterator<char>(in)),{});game_load_functions loader(p.st());auto setup=[&]{loader.setup_info.create_no_units=true;for(auto& v:p.st().players){v.race=race_t::terran;v.controller=player_t::controller_occupied;}};loader.load_map_data(map.data(),map.size(),setup);
 // Isolated flat arena: repeat one fully walkable/buildable owned tileset tile.
 // This fixture geometry is never exported or substituted for a mission map.
 unsigned tile=0;bool found=false;for(unsigned i=0;i<p.st().tiles.size();++i){auto flags=p.st().tiles[i].flags;if((flags&tile_t::flag_walkable) && !(flags&(tile_t::flag_partially_walkable|tile_t::flag_unbuildable))){tile=p.st().game->gfx_tiles[i].raw_value;found=true;break;}}assert(found);for(unsigned at=0;at+8<=map.size();){unsigned n=unsigned(map[at+4])|unsigned(map[at+5])<<8|unsigned(map[at+6])<<16|unsigned(map[at+7])<<24;if(!memcmp(map.data()+at,"MTXM",4))for(unsigned j=0;j<n;j+=2){map[at+8+j]=tile;map[at+9+j]=tile>>8;}at+=8+n;}loader.load_map_data(map.data(),map.size(),setup);p.st().game->triggers.clear();for(auto& t:p.st().running_triggers)t.clear();}
static unit_t* create(state_functions& f,UnitTypes type,xy pos,unsigned owner=0){f.reveal_sight_at(pos,11,1u<<owner,true);auto* u=f.trigger_create_unit(f.get_unit_type(type),pos,owner);if(!u)fprintf(stderr,"create failed type%u pos%d,%d map%u,%u\n",unsigned(type),pos.x,pos.y,unsigned(f.st.game->map_width),unsigned(f.st.game->map_height));assert(u);return u;}
int main(int argc,char**argv){assert(argc==3);auto assets=data_loading::data_files_directory(argv[1]);
 {game_player p(assets);init(p,argv[2]);auto& f=p.funcs();auto& st=p.st();CampaignAI ai;auto* dt=create(f,UnitTypes::Protoss_Dark_Templar,{500,500});auto* hero=create(f,UnitTypes::Hero_Dark_Templar,{550,500});auto* other=create(f,UnitTypes::Protoss_Zealot,{600,500});auto* enemy=create(f,UnitTypes::Protoss_Dark_Templar,{500,600},1);code(ai,{38,36});ai.start(f,0x54534554,0,{1300,1300});assert(dt->order_type->id==Orders::Move && hero->order_type->id==Orders::Move && other->order_type->id!=Orders::Move && enemy->order_type->id!=Orders::Move);auto before=dt->sprite->position;for(unsigned n=0;n<200;++n){f.next_frame();ai.step(f);}auto d=dt->sprite->position-before;assert(d.x*d.x+d.y*d.y>200*200);puts("move_dt: own completed hero/ordinary Dark Templar actually move, other types/owners excluded PASS");}
 {game_player p(assets);init(p,argv[2]);auto& f=p.funcs();auto& st=p.st();CampaignAI ai;st.current_minerals[0]=123;st.current_gas[0]=45;code(ai,{108,0,0,232,3,232,3,87,1,36});ai.start(f,0x54534554,0,{});assert(st.completed_unit_counts[0][UnitTypes::Terran_Marine]==1 && (st.shared_vision[1]&1));assert(st.current_minerals[0]==123 && st.current_gas[0]==45);for(auto* u:ptr(st.player_units[0]))assert(u->sprite->position==xy(1000,1000));for(unsigned n=0;n<60;++n){f.next_frame();ai.step(f);}assert(st.completed_unit_counts[0][UnitTypes::Terran_Marine]==1);code(ai,{108,228,0,0,0,0,0,36});bool rejected=false;try{ai.start(f,0x54534554,0,{});}catch(const std::runtime_error&){rejected=true;}assert(rejected);puts("create_unit: explicit one-shot scenario grant, correct owner/coordinates, no repeat, invalid type rejected PASS");}
 for(unsigned op:{103u,104u}){game_player p(assets);init(p,argv[2]);auto& f=p.funcs();auto& st=p.st();auto tech=op==103?TechTypes::Disruption_Web:TechTypes::Recall;auto type=op==103?UnitTypes::Protoss_Corsair:UnitTypes::Protoss_Arbiter;auto* caster=create(f,type,{700,700});auto* tired=create(f,type,{1400,1400});caster->energy=fp8::integer(250);tired->energy=fp8::integer(0);auto* marine=create(f,UnitTypes::Terran_Marine,{1500,1500});for(unsigned settle=0;settle<8;++settle)f.next_frame();st.game->tech_available[0][tech]=true;st.tech_researched[0][tech]=true;CampaignAI ai;code(ai,{uint8_t(op),36});ai.start(f,0x54534554,0,{1500,1500});assert(caster->order_type->id==(op==103?Orders::CastDisruptionWeb:Orders::CastRecall));assert(tired->order_type->tech_type==TechTypes::None);bool effect=false,paid=false;for(unsigned n=0;n<500 && !effect;++n){f.next_frame();ai.step(f);paid|=caster->energy<fp8::integer(200);if(op==103){for(auto* u:ptr(st.visible_units))if(f.unit_is(u,UnitTypes::Spell_Disruption_Web))effect=true;}else{auto d=marine->sprite->position-caster->sprite->position;effect=d.x*d.x+d.y*d.y<160*160;}}fprintf(stderr,"spell%u native_effect%d energy_paid%d\n",op,effect,paid);assert(effect && paid);puts("location spell: researched eligible caster chosen over exhausted nearest, actual native effect and energy cost PASS");}
}
